    finance: [[['เลขที่สัญญา', 'สญ2-จซ-' + viPad(1 + (n % 200), 3) + '-' + (year - 1)]], [['งวดที่ส่งมอบ', 'งวดที่ ' + (1 + (n % 3))]], [['มูลค่ายานพาหนะ', viNum(spec[4]) + '.00']]].map(items => ({ items, half: true })),
