const PLAN_TABS = ['รายละเอียดแผน', 'ต้นทุนการบำรุงรักษา'];
const COST_CANNOT = TRIP_1.sel[2];   // คันที่บำรุงรักษาไม่ได้ของ T1 (JOB_MIX)
